// 全項目を置き換える。versionが一致しない場合は0件となる。
func (q *Queries) UpdateItem(ctx context.Context, arg UpdateItemParams) (OwnershipItem, error) {
	row := q.db.QueryRow(ctx, updateItem,
		arg.CategoryID,
		arg.Name,
		arg.ItemKindCode,
		arg.Quantity,
		arg.UnitName,
		arg.NecessityLevelCode,
		arg.UsageFrequencyCode,
		arg.PurchasedOn,
		arg.SourceUrl,
		arg.Notes,
		arg.UpdatedAt,
		arg.PublicID,
		arg.UserID,
		arg.ExpectedVersion,
	)
	var i OwnershipItem
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.UserID,
		&i.CategoryID,
		&i.Name,
		&i.ItemKindCode,
		&i.Quantity,
		&i.UnitName,
		&i.NecessityLevelCode,
		&i.UsageFrequencyCode,
		&i.PurchasedOn,
		&i.SourceUrl,
		&i.Notes,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Version,
	)
	return i, err
}
